import React from 'react';
import { createRoot } from 'react-dom/client';
import { AppProvider } from './state/store';
import { AppContent } from './App';

const container = document.getElementById('root');
if (container) {
  const root = createRoot(container);
  root.render(
    <React.StrictMode>
      <AppProvider>
        <AppContent />
      </AppProvider>
    </React.StrictMode>
  );
}
